INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Change of Mailing or Home Address', 'All dentists and hygienists are required to notify the board within 30 days of their change of mailing address.', 'change_of_info', '/documents/applications/mailinghomeaddress.pdf', 'documents/applications/mailinghomeaddress.pdf', 314401, false, NULL, 10, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Change of Practice Location (dentists only)', 'All Louisiana dentists are required to notify the board of any changes of practice location within 30 days of the date of the change. If you add a new practice location, it will NOT automatically remove another location. You must submit one form to add a new practice location and a separate form to remove the former practice location. Notifying the board of your change of practice location will NOT change your official mailing address on file with the board.', 'change_of_info', '/documents/applications/practicelocation.pdf', 'documents/applications/practicelocation.pdf', 273076, false, NULL, 20, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Change of Employer (hygienists only)', 'All Louisiana hygienists are required to notify the board of any changes in their employing dentist within 30 days of the date of the change. If you add a new employer to your record, it will NOT automatically remove another employer. You must submit one form to add a new employer and a separate form to remove the former employer. Notifying the board of your change of employer and practice location will NOT change your official mailing address on file with the board.', 'change_of_info', '/documents/applications/employerchange.pdf', 'documents/applications/employerchange.pdf', 271958, false, NULL, 30, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Nitrous Oxide Personal Permit Application', 'The Board no longer issues office nitrous permits. A personal nitrous permit is all that is required to administer nitrous oxide.', 'dental_anesthesia', '/documents/applications/nitrous-oxide-application.pdf', 'documents/applications/nitrous-oxide-application.pdf', 231967, false, NULL, 10, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Moderate Sedation Personal and Office Permit Application', NULL, 'dental_anesthesia', '/documents/applications/moderateapplication.pdf', 'documents/applications/moderateapplication.pdf', 419851, false, NULL, 20, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('General Anesthesia Personal and Office Permit Application', NULL, 'dental_anesthesia', '/documents/applications/generalanesthesiaapplication.pdf', 'documents/applications/generalanesthesiaapplication.pdf', 420508, false, NULL, 30, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Anesthesia Inspection Sheet', 'Office permits for any level of anesthesia other than nitrous oxide require an office inspection. Please use the following inspection sheet as a checklist to ensure you have the appropriate equipment and information available for the inspector.', 'dental_anesthesia', '/documents/forms/anesthesiainspection.pdf', 'documents/forms/anesthesiainspection.pdf', 127550, false, NULL, 40, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Dental Hygiene Nitrous Oxide Permit Application', NULL, 'hygiene_anesthesia', '/documents/applications/hygienenitrousoxideapplication.pdf', 'documents/applications/hygienenitrousoxideapplication.pdf', 249467, false, NULL, 10, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Dental Hygiene Local Anesthesia Permit Application', NULL, 'hygiene_anesthesia', '/documents/applications/hygiene-anesthesia-application.pdf', 'documents/applications/hygiene-anesthesia-application.pdf', 385947, false, NULL, 20, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Local Anesthesia Affidavit', 'If you have been licensed and permitted in another state to administer local anesthesia in your practice of dental hygiene, and you wish to apply for a permit to administer local anesthesia in Louisiana, please also fill out the affidavit and submit it with your local anesthesia permit application.', 'hygiene_anesthesia', '/documents/applications/local-anesthesia-affidavit.pdf', 'documents/applications/local-anesthesia-affidavit.pdf', 186292, false, NULL, 30, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Mobile Dental Office Permit Application', 'A mobile office is a self-contained movable facility such as an RV. A mobile dental office permit will only be issued to a Louisiana licensed dentist.', 'mobile_portable', '/documents/forms/mobilepermit.pdf', 'documents/forms/mobilepermit.pdf', 286688, false, NULL, 10, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Portable Dental Office Permit Application', 'A portable office consists of portable dental equipment which is set up on site. A portable dental office permit will only be issued to a Louisiana licensed dentist.', 'mobile_portable', '/documents/forms/portablepermit.pdf', 'documents/forms/portablepermit.pdf', 285458, false, NULL, 20, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Affidavit for Opioid Management CE Exemption (dentists only)', 'Dentists who do not prescribe, dispense, or administer any controlled substances are not required to complete the 3 hours of opioid management continuing education. Complete this affidavit in the presence of a notary and mail it to the board office. We will then verify you have not prescribed, dispensed, or administered any controlled substances with the Prescription Monitoring Program. Should you prescribe, dispense, or administer controlled substances in the future, you will be required to obtain the opioid management CE.', 'opioid', '/documents/forms/affidavitnocds.pdf', 'documents/forms/affidavitnocds.pdf', 111369, false, NULL, 10, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Sample Inspection Notice', 'This is an example of the notice a dentist should receive approximately one week prior to the scheduled CDC inspection.', 'cdc_inspection', '/documents/forms/inspectionnotice.pdf', 'documents/forms/inspectionnotice.pdf', 294061, false, NULL, 10, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Inspection Form', 'The inspector will use this form when inspecting the dentist''s office. Please use the inspection sheet as a checklist so that the appropriate equipment and documentation is available for the inspector.', 'cdc_inspection', '/documents/forms/cdcinspection.pdf', 'documents/forms/cdcinspection.pdf', 215214, false, NULL, 20, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('HBV Vaccine Declination', 'Dentists are required to offer certain personnel the Hepatitis B vaccine at no charge. The dentist should maintain information regarding the staff''s HBV vaccinations. If any employee refuses the HBV vaccine, a declination statement should be maintained in the dentist''s office. The declination form is an example of this statement.', 'cdc_inspection', '/documents/forms/hbvdeclination.pdf', 'documents/forms/hbvdeclination.pdf', 180225, false, NULL, 30, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Sample Controlled Substances Log Form', 'All dentists are required to maintain an accurate running total of controlled substances in their possession. Please see the sample file for your convenience. This form should be maintained by the dentist. Do not submit this form to the board.', 'controlled_substances', '/documents/forms/controlledsubstanceslog.pdf', 'documents/forms/controlledsubstanceslog.pdf', 74536, false, NULL, 10, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('EDDA Application', 'Expanded Duty Dental Assistants. You may apply for the EDDA certificate confirmation by submitting the EDDA application, a copy of your proof of completion of the EDDA course, BLS course, and radiology course along with the application fee of $100 to the Board office. DO NOT SEND CASH.', 'additional', '/documents/applications/edda-application.pdf', 'documents/applications/edda-application.pdf', 160875, false, NULL, 10, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Expungement Application', 'Application for Expungement of First Time Advertising Violations', 'additional', '/documents/applications/expungementapplication.pdf', 'documents/applications/expungementapplication.pdf', 63281, false, NULL, 20, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Dental Information Sheet', 'Newly licensed dentists only', 'miscellaneous', '/documents/forms/dentalinfo.pdf', 'documents/forms/dentalinfo.pdf', 265000, false, NULL, 10, true);
