INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Complaint Form', 'To lodge a complaint against a licensee, please download the form, fill it out, and then return it to our office. You may email, fax, or mail it.', 'miscellaneous', '/documents/forms/complaintform.pdf', 'documents/forms/complaintform.pdf', 172538, false, NULL, 50, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Dental License by Examination (LBE) Application', 'You may qualify for a dental license by examination if you completed the ADEX examination within FIVE years of applying for a Louisiana license.', 'license_applications', '/documents/applications/lbeapplicationdental.pdf', 'documents/applications/lbeapplicationdental.pdf', 1453304, false, NULL, 10, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Dental Hygiene License by Examination (LBE) Application', 'You may qualify for a dental hygiene license by examination if you completed the ADEX examination within THREE years of applying for a Louisiana license.', 'license_applications', '/documents/applications/lbeapplicationhygiene.pdf', 'documents/applications/lbeapplicationhygiene.pdf', 1448400, false, NULL, 20, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Dental License by Credentials (LBC) Application', 'You may qualify for a regular dental license by credentials if you currently hold a license in another state and have practiced at least 1000 hours each year for the immediately preceding three years.', 'license_applications', '/documents/forms/dentallbc.pdf', 'documents/forms/dentallbc.pdf', 1757042, false, NULL, 30, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Dental Hygiene License by Credentials (LBC) Application', 'You may qualify for a regular dental hygiene license by credentials if you currently hold a license in another state and have practiced at least 1000 hours for the immediately preceding year.', 'license_applications', '/documents/forms/hygienelbc.pdf', 'documents/forms/hygienelbc.pdf', 1641335, false, NULL, 40, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Dental License by Credentials (LBC) Application - Louisiana Residents', 'You must currently reside in Louisiana and hold a license in another state to use this application.', 'license_applications', '/documents/forms/dentallbc-la-resident.pdf', 'documents/forms/dentallbc-la-resident.pdf', 1477627, false, NULL, 50, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Dental Hygiene License by Credentials (LBC) Application - Louisiana Residents', 'You must reside in Louisiana and currently hold a license in another state to use this application.', 'license_applications', '/documents/forms/hygienelbc-la-resident.pdf', 'documents/forms/hygienelbc-la-resident.pdf', 1445412, false, NULL, 60, true);
INSERT INTO public.downloadable_forms (name, description, category, blob_url, blob_pathname, file_size_bytes, is_external, external_url, sort_order, is_active) VALUES ('Restricted License Application', 'Restricted licenses are for dentists participating in postgraduate programs in Louisiana or instructors in Louisiana dental education.', 'license_applications', '/documents/forms/restrictedapplication.pdf', 'documents/forms/restrictedapplication.pdf', 369015, false, NULL, 70, true);
